import type { BlogPost } from './types';
import type { ResearchPost } from './types';

export const november09BlogPosts: readonly BlogPost[] = [{"slug":"build-a-rate-increase-notice-tracker-the-billing-team-can-trust","title":"Build a rate increase notice tracker the billing team can trust","description":"A notice tracker that connects each approved rate change to the client notice, effective date, affected matters, and first invoice check.","category":"Rate management","readTime":"9 min read","thumbnail":"/thumbnails/november-09/build-a-rate-increase-notice-tracker-the-billing-team-can-trust.webp","internalService":"/services/billing-reporting-support","internalSibling":"/blog/write-a-timekeeper-onboarding-packet-for-client-billing-rules","source":{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},"sections":[{"heading":"Begin with the client notice, not the rate table","paragraphs":["a rate increase notice works only when the team can connect a request to its source and its owner. The process starts when a partner or finance owner approves a new rate, and it should leave a dated record in the billing and matter systems. The billing assistant gathers the signed rate notice and the client approval, then checks the effective date against the affected matter list. A rate notice that reaches billing after the invoice run is a client problem, not an administrative detail.","A useful the rate notice tracker answers four questions in one place. It shows what changed, who approved the change, when it took effect, and which records depend on it. Those answers belong beside the case rather than in a separate email thread. A reviewer should reconstruct the path without asking the preparer for context."]},{"heading":"Record the effective date and the approval chain","paragraphs":["a rate increase notice works only when the team can connect a request to its source and its owner. The process starts when a partner or finance owner approves a new rate, and it should leave a dated record in the billing and matter systems. The billing assistant gathers the signed rate notice and the client approval, then checks the effective date against the affected matter list. Record the notice date separately from the effective date so the team can see how much lead time it had.","The approval chain matters as much as the final value. Name who prepared the case, who reviewed it, and who had authority to approve the decision to apply the new rate. Keep the approval date next to the value so a later reader can see when the state changed. A value without an approval trail is an assertion, not a controlled record."]},{"heading":"Separate standard increases from exception pricing","paragraphs":["a rate increase notice works only when the team can connect a request to its source and its owner. The process starts when a partner or finance owner approves a new rate, and it should leave a dated record in the billing and matter systems. The billing assistant gathers the signed rate notice and the client approval, then checks the effective date against the affected matter list. A client-specific exception rate needs its own line, because a standard increase should not overwrite it.","Keep a short list of exception types and the evidence each one requires. A missing document, a client instruction, and an internal correction should not share one code. The code should point to the fix, whether that is a source request, a template change, or an approval step. When the same exception repeats, treat it as a process gap rather than a one-off mistake."]},{"heading":"Map each notice to affected matters and timekeepers","paragraphs":["a rate increase notice works only when the team can connect a request to its source and its owner. The process starts when a partner or finance owner approves a new rate, and it should leave a dated record in the billing and matter systems. The billing assistant gathers the signed rate notice and the client approval, then checks the effective date against the affected matter list. Map the notice to every open matter and to the timekeepers who bill them.","Define the fields before the first entry and keep them stable. Use one field for the source, one for the decision, one for the effective date, and one for the next action in the billing and matter systems. Free-text notes are useful for context but should not be the only place where an owner or deadline appears. Stable fields make the queue sortable and let a reviewer find the cases that need attention."]},{"heading":"Create a queue for missing or late notices","paragraphs":["a rate increase notice works only when the team can connect a request to its source and its owner. The process starts when a partner or finance owner approves a new rate, and it should leave a dated record in the billing and matter systems. The billing assistant gathers the signed rate notice and the client approval, then checks the effective date against the affected matter list. A missing notice is the most important item in the queue, even when no invoice is due yet.","Set a response rule for each type of wait. A missing receipt may allow a short grace period, while a missing client authorization should pause the charge. Record the rule and the date the case last changed so a reviewer can see whether it is moving. Do not close a case just because the deadline passed, because an unresolved exception should stay visible."]},{"heading":"Test the tracker against a recent increase","paragraphs":["a rate increase notice works only when the team can connect a request to its source and its owner. The process starts when a partner or finance owner approves a new rate, and it should leave a dated record in the billing and matter systems. The billing assistant gathers the signed rate notice and the client approval, then checks the effective date against the affected matter list. Use a completed increase to test whether the tracker captures the approval and the first invoice effect.","Run the test on two different matter types before adopting the template. A routine matter and an exception case should both produce a readable record, even if they need different evidence. Keep the test notes with the template version so the change is traceable. A tool that has never been used by a second person is still a draft."]},{"heading":"Report status without exposing client terms","paragraphs":["a rate increase notice works only when the team can connect a request to its source and its owner. The process starts when a partner or finance owner approves a new rate, and it should leave a dated record in the billing and matter systems. The billing assistant gathers the signed rate notice and the client approval, then checks the effective date against the affected matter list. Summaries for management should count late notices and affected matters without listing client rates.","Give each audience the view it needs to act. The billing manager needs the exception and the decision, while the billing team needs the owner and the next action. A partner summary should show exposure and timing rather than a long list of routine cases. Limit access to the people who need the record, and review permissions when a role changes."]},{"heading":"Close the loop on the first invoice","paragraphs":["a rate increase notice works only when the team can connect a request to its source and its owner. The process starts when a partner or finance owner approves a new rate, and it should leave a dated record in the billing and matter systems. The billing assistant gathers the signed rate notice and the client approval, then checks the effective date against the affected matter list. The first invoice after the change is the proof that the tracker worked.","Set a review cadence of each billing cycle and keep the definitions stable. Review the evidence with the billing manager and the person who maintains the rate notice tracker. Choose one change that would prevent the most rework, and give it a named owner and a date. The next review should test whether that change worked without adding hidden exceptions."]}],"faq":[{"q":"Who owns a rate increase notice?","a":"The billing manager owns the decision to apply the new rate; the billing assistant prepares the evidence and flags exceptions."},{"q":"What proves that the rate notice tracker is complete?","a":"A reviewer can see the signed rate notice, the approval, the effective date, and the next action without asking the preparer."},{"q":"When should the team review this?","a":"Review it each billing cycle and after any change to the client requirement or the billing system."}],"publishedAt":"2026-11-09"},{"slug":"write-a-timekeeper-onboarding-packet-for-client-billing-rules","title":"Write a timekeeper onboarding packet for client billing rules","description":"A packet that turns client billing rules into first-week checkpoints for a new timekeeper, with examples, escalation paths, and a reviewer.","category":"Billing guidelines","readTime":"9 min read","thumbnail":"/thumbnails/november-09/write-a-timekeeper-onboarding-packet-for-client-billing-rules.webp","internalService":"/services/time-entry-review-support","internalSibling":"/blog/build-a-disbursement-cost-checklist-for-invoice-review","source":{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},"sections":[{"heading":"Open with the rules that change daily work","paragraphs":["timekeeper onboarding works only when the team can connect a request to its source and its owner. The process starts when a new timekeeper joins a client matter, and it should leave a dated record in the time and billing platform. The billing assistant gathers the client billing guidelines and the matter budget, then checks the approved rate card against the sample entries. A new timekeeper needs the client rules that change how work is described, not a general policy manual.","A useful the onboarding packet answers four questions in one place. It shows what changed, who approved the change, when it took effect, and which records depend on it. Those answers belong beside the case rather than in a separate email thread. A reviewer should reconstruct the path without asking the preparer for context."]},{"heading":"Translate each rule into a review checkpoint","paragraphs":["timekeeper onboarding works only when the team can connect a request to its source and its owner. The process starts when a new timekeeper joins a client matter, and it should leave a dated record in the time and billing platform. The billing assistant gathers the client billing guidelines and the matter budget, then checks the approved rate card against the sample entries. Translate each rule into a checkpoint the timekeeper can apply while entering time.","The approval chain matters as much as the final value. Name who prepared the case, who reviewed it, and who had authority to approve the decision to release the timekeeper to independent entry. Keep the approval date next to the value so a later reader can see when the state changed. A value without an approval trail is an assertion, not a controlled record."]},{"heading":"Show where time and expenses are captured","paragraphs":["timekeeper onboarding works only when the team can connect a request to its source and its owner. The process starts when a new timekeeper joins a client matter, and it should leave a dated record in the time and billing platform. The billing assistant gathers the client billing guidelines and the matter budget, then checks the approved rate card against the sample entries. Show where the narrative, the task code, and the expense field live in the system.","Keep a short list of exception types and the evidence each one requires. A missing document, a client instruction, and an internal correction should not share one code. The code should point to the fix, whether that is a source request, a template change, or an approval step. When the same exception repeats, treat it as a process gap rather than a one-off mistake."]},{"heading":"Explain the exception path before the first entry","paragraphs":["timekeeper onboarding works only when the team can connect a request to its source and its owner. The process starts when a new timekeeper joins a client matter, and it should leave a dated record in the time and billing platform. The billing assistant gathers the client billing guidelines and the matter budget, then checks the approved rate card against the sample entries. The exception path should be visible before the first entry, not discovered after a rejection.","Define the fields before the first entry and keep them stable. Use one field for the source, one for the decision, one for the effective date, and one for the next action in the time and billing platform. Free-text notes are useful for context but should not be the only place where an owner or deadline appears. Stable fields make the queue sortable and let a reviewer find the cases that need attention."]},{"heading":"Give the new timekeeper a practice sample","paragraphs":["timekeeper onboarding works only when the team can connect a request to its source and its owner. The process starts when a new timekeeper joins a client matter, and it should leave a dated record in the time and billing platform. The billing assistant gathers the client billing guidelines and the matter budget, then checks the approved rate card against the sample entries. A practice sample with a corrected example teaches more than a list of prohibitions.","Set a response rule for each type of wait. A missing receipt may allow a short grace period, while a missing client authorization should pause the charge. Record the rule and the date the case last changed so a reviewer can see whether it is moving. Do not close a case just because the deadline passed, because an unresolved exception should stay visible."]},{"heading":"Assign a reviewer for the first cycle","paragraphs":["timekeeper onboarding works only when the team can connect a request to its source and its owner. The process starts when a new timekeeper joins a client matter, and it should leave a dated record in the time and billing platform. The billing assistant gathers the client billing guidelines and the matter budget, then checks the approved rate card against the sample entries. Assign a reviewer for the first cycle and tell the timekeeper how to ask for help.","Run the test on two different matter types before adopting the template. A routine matter and an exception case should both produce a readable record, even if they need different evidence. Keep the test notes with the template version so the change is traceable. A tool that has never been used by a second person is still a draft."]},{"heading":"Collect questions and update the packet","paragraphs":["timekeeper onboarding works only when the team can connect a request to its source and its owner. The process starts when a new timekeeper joins a client matter, and it should leave a dated record in the time and billing platform. The billing assistant gathers the client billing guidelines and the matter budget, then checks the approved rate card against the sample entries. Collect the questions from the first month and update the packet once, with a date.","Give each audience the view it needs to act. The supervising partner needs the exception and the decision, while the billing team needs the owner and the next action. A partner summary should show exposure and timing rather than a long list of routine cases. Limit access to the people who need the record, and review permissions when a role changes."]},{"heading":"Keep the packet versioned and dated","paragraphs":["timekeeper onboarding works only when the team can connect a request to its source and its owner. The process starts when a new timekeeper joins a client matter, and it should leave a dated record in the time and billing platform. The billing assistant gathers the client billing guidelines and the matter budget, then checks the approved rate card against the sample entries. Keep a version number so a reviewer can tell which rules the timekeeper received.","Set a review cadence of the first two billing cycles and keep the definitions stable. Review the evidence with the supervising partner and the person who maintains the onboarding packet. Choose one change that would prevent the most rework, and give it a named owner and a date. The next review should test whether that change worked without adding hidden exceptions."]}],"faq":[{"q":"Who owns timekeeper onboarding?","a":"The supervising partner owns the decision to release the timekeeper to independent entry; the billing assistant prepares the evidence and flags exceptions."},{"q":"What proves that the onboarding packet is complete?","a":"A reviewer can see the client billing guidelines, the approval, the effective date, and the next action without asking the preparer."},{"q":"When should the team review this?","a":"Review it the first two billing cycles and after any change to the client requirement or the billing system."}],"publishedAt":"2026-11-09"},{"slug":"build-a-disbursement-cost-checklist-for-invoice-review","title":"Build a disbursement cost checklist for invoice review","description":"A cost checklist that keeps receipts, client authorization, matter references, and tax treatment visible before a disbursement reaches the invoice.","category":"Disbursements","readTime":"9 min read","thumbnail":"/thumbnails/november-09/build-a-disbursement-cost-checklist-for-invoice-review.webp","internalService":"/services/invoice-follow-up","internalSibling":"/blog/prepare-a-trust-to-operating-transfer-review-without-moving-funds","source":{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},"sections":[{"heading":"List the cost types the firm actually bills","paragraphs":["a disbursement cost works only when the team can connect a request to its source and its owner. The process starts when a cost is posted to a client matter, and it should leave a dated record in the accounting and billing systems. The billing assistant gathers the vendor receipt and the client authorization, then checks the matter reference against the tax treatment note. A disbursement is billable only when the cost, the client authorization, and the matter are connected.","A useful the cost checklist answers four questions in one place. It shows what changed, who approved the change, when it took effect, and which records depend on it. Those answers belong beside the case rather than in a separate email thread. A reviewer should reconstruct the path without asking the preparer for context."]},{"heading":"Separate client costs from firm overhead","paragraphs":["a disbursement cost works only when the team can connect a request to its source and its owner. The process starts when a cost is posted to a client matter, and it should leave a dated record in the accounting and billing systems. The billing assistant gathers the vendor receipt and the client authorization, then checks the matter reference against the tax treatment note. List the cost types the firm bills, such as filing fees, couriers, experts, and travel.","The approval chain matters as much as the final value. Name who prepared the case, who reviewed it, and who had authority to approve the decision to bill the cost to the client. Keep the approval date next to the value so a later reader can see when the state changed. A value without an approval trail is an assertion, not a controlled record."]},{"heading":"Require a receipt and a matter reference","paragraphs":["a disbursement cost works only when the team can connect a request to its source and its owner. The process starts when a cost is posted to a client matter, and it should leave a dated record in the accounting and billing systems. The billing assistant gathers the vendor receipt and the client authorization, then checks the matter reference against the tax treatment note. Separate a client cost from firm overhead before the amount reaches the invoice.","Keep a short list of exception types and the evidence each one requires. A missing document, a client instruction, and an internal correction should not share one code. The code should point to the fix, whether that is a source request, a template change, or an approval step. When the same exception repeats, treat it as a process gap rather than a one-off mistake."]},{"heading":"Flag costs that need client pre-approval","paragraphs":["a disbursement cost works only when the team can connect a request to its source and its owner. The process starts when a cost is posted to a client matter, and it should leave a dated record in the accounting and billing systems. The billing assistant gathers the vendor receipt and the client authorization, then checks the matter reference against the tax treatment note. A receipt and a matter reference should be required for every cost line.","Define the fields before the first entry and keep them stable. Use one field for the source, one for the decision, one for the effective date, and one for the next action in the accounting and billing systems. Free-text notes are useful for context but should not be the only place where an owner or deadline appears. Stable fields make the queue sortable and let a reviewer find the cases that need attention."]},{"heading":"Check the invoice against the cost ledger","paragraphs":["a disbursement cost works only when the team can connect a request to its source and its owner. The process starts when a cost is posted to a client matter, and it should leave a dated record in the accounting and billing systems. The billing assistant gathers the vendor receipt and the client authorization, then checks the matter reference against the tax treatment note. Pre-approval matters most for costs the client did not expect when the engagement began.","Set a response rule for each type of wait. A missing receipt may allow a short grace period, while a missing client authorization should pause the charge. Record the rule and the date the case last changed so a reviewer can see whether it is moving. Do not close a case just because the deadline passed, because an unresolved exception should stay visible."]},{"heading":"Handle tax and currency differences explicitly","paragraphs":["a disbursement cost works only when the team can connect a request to its source and its owner. The process starts when a cost is posted to a client matter, and it should leave a dated record in the accounting and billing systems. The billing assistant gathers the vendor receipt and the client authorization, then checks the matter reference against the tax treatment note. Compare the invoice line with the cost ledger and the source receipt before release.","Run the test on two different matter types before adopting the template. A routine matter and an exception case should both produce a readable record, even if they need different evidence. Keep the test notes with the template version so the change is traceable. A tool that has never been used by a second person is still a draft."]},{"heading":"Review duplicates and unusual amounts","paragraphs":["a disbursement cost works only when the team can connect a request to its source and its owner. The process starts when a cost is posted to a client matter, and it should leave a dated record in the accounting and billing systems. The billing assistant gathers the vendor receipt and the client authorization, then checks the matter reference against the tax treatment note. Tax and currency differences need an explicit note, not a silent adjustment.","Give each audience the view it needs to act. The billing manager needs the exception and the decision, while the billing team needs the owner and the next action. A partner summary should show exposure and timing rather than a long list of routine cases. Limit access to the people who need the record, and review permissions when a role changes."]},{"heading":"Close the cost file at invoice approval","paragraphs":["a disbursement cost works only when the team can connect a request to its source and its owner. The process starts when a cost is posted to a client matter, and it should leave a dated record in the accounting and billing systems. The billing assistant gathers the vendor receipt and the client authorization, then checks the matter reference against the tax treatment note. Close the cost file when the invoice is approved so the same receipt cannot be billed twice.","Set a review cadence of each invoice cycle and keep the definitions stable. Review the evidence with the billing manager and the person who maintains the cost checklist. Choose one change that would prevent the most rework, and give it a named owner and a date. The next review should test whether that change worked without adding hidden exceptions."]}],"faq":[{"q":"Who owns a disbursement cost?","a":"The billing manager owns the decision to bill the cost to the client; the billing assistant prepares the evidence and flags exceptions."},{"q":"What proves that the cost checklist is complete?","a":"A reviewer can see the vendor receipt, the approval, the effective date, and the next action without asking the preparer."},{"q":"When should the team review this?","a":"Review it each invoice cycle and after any change to the client requirement or the billing system."}],"publishedAt":"2026-11-09"},{"slug":"prepare-a-trust-to-operating-transfer-review-without-moving-funds","title":"Prepare a trust-to-operating transfer review without moving funds","description":"A review packet that documents the client authorization, earned fees, available balance, and approval path before anyone moves trust funds.","category":"Trust accounting","readTime":"9 min read","thumbnail":"/thumbnails/november-09/prepare-a-trust-to-operating-transfer-review-without-moving-funds.webp","internalService":"/services/matter-record-upkeep","internalSibling":"/blog/build-a-client-portal-rejection-log-reviewers-can-scan","source":{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},"sections":[{"heading":"Confirm the request before preparing anything","paragraphs":["a trust-to-operating transfer works only when the team can connect a request to its source and its owner. The process starts when the firm believes fees have been earned, and it should leave a dated record in the trust ledger and billing system. The billing assistant gathers the client authorization and the invoice and payment history, then checks the trust ledger balance against the earned fee calculation. A trust transfer review starts with the client authorization, not with the firm's need for payment.","A useful the transfer review packet answers four questions in one place. It shows what changed, who approved the change, when it took effect, and which records depend on it. Those answers belong beside the case rather than in a separate email thread. A reviewer should reconstruct the path without asking the preparer for context."]},{"heading":"Identify the client authorization and purpose","paragraphs":["a trust-to-operating transfer works only when the team can connect a request to its source and its owner. The process starts when the firm believes fees have been earned, and it should leave a dated record in the trust ledger and billing system. The billing assistant gathers the client authorization and the invoice and payment history, then checks the trust ledger balance against the earned fee calculation. Identify the purpose, the amount requested, and the invoice or fee the transfer is meant to satisfy.","The approval chain matters as much as the final value. Name who prepared the case, who reviewed it, and who had authority to approve the decision to authorize the transfer. Keep the approval date next to the value so a later reader can see when the state changed. A value without an approval trail is an assertion, not a controlled record."]},{"heading":"Match the matter and the ledger account","paragraphs":["a trust-to-operating transfer works only when the team can connect a request to its source and its owner. The process starts when the firm believes fees have been earned, and it should leave a dated record in the trust ledger and billing system. The billing assistant gathers the client authorization and the invoice and payment history, then checks the trust ledger balance against the earned fee calculation. Match the client and matter to the trust ledger account before calculating anything.","Keep a short list of exception types and the evidence each one requires. A missing document, a client instruction, and an internal correction should not share one code. The code should point to the fix, whether that is a source request, a template change, or an approval step. When the same exception repeats, treat it as a process gap rather than a one-off mistake."]},{"heading":"Calculate available funds without moving them","paragraphs":["a trust-to-operating transfer works only when the team can connect a request to its source and its owner. The process starts when the firm believes fees have been earned, and it should leave a dated record in the trust ledger and billing system. The billing assistant gathers the client authorization and the invoice and payment history, then checks the trust ledger balance against the earned fee calculation. Calculate the available balance from the ledger and keep the calculation with the request.","Define the fields before the first entry and keep them stable. Use one field for the source, one for the decision, one for the effective date, and one for the next action in the trust ledger and billing system. Free-text notes are useful for context but should not be the only place where an owner or deadline appears. Stable fields make the queue sortable and let a reviewer find the cases that need attention."]},{"heading":"Route the approval to the right owner","paragraphs":["a trust-to-operating transfer works only when the team can connect a request to its source and its owner. The process starts when the firm believes fees have been earned, and it should leave a dated record in the trust ledger and billing system. The billing assistant gathers the client authorization and the invoice and payment history, then checks the trust ledger balance against the earned fee calculation. Route the approval to the attorney and finance owner who can authorize the movement.","Set a response rule for each type of wait. A missing receipt may allow a short grace period, while a missing client authorization should pause the charge. Record the rule and the date the case last changed so a reviewer can see whether it is moving. Do not close a case just because the deadline passed, because an unresolved exception should stay visible."]},{"heading":"Record the decision and the effective date","paragraphs":["a trust-to-operating transfer works only when the team can connect a request to its source and its owner. The process starts when the firm believes fees have been earned, and it should leave a dated record in the trust ledger and billing system. The billing assistant gathers the client authorization and the invoice and payment history, then checks the trust ledger balance against the earned fee calculation. Record the decision, the amount approved, and the date the transfer will take effect.","Run the test on two different matter types before adopting the template. A routine matter and an exception case should both produce a readable record, even if they need different evidence. Keep the test notes with the template version so the change is traceable. A tool that has never been used by a second person is still a draft."]},{"heading":"Handle partial approvals and refusals","paragraphs":["a trust-to-operating transfer works only when the team can connect a request to its source and its owner. The process starts when the firm believes fees have been earned, and it should leave a dated record in the trust ledger and billing system. The billing assistant gathers the client authorization and the invoice and payment history, then checks the trust ledger balance against the earned fee calculation. A partial approval needs a written reason and a new calculation, not a silent reduction.","Give each audience the view it needs to act. The responsible attorney and finance owner needs the exception and the decision, while the billing team needs the owner and the next action. A partner summary should show exposure and timing rather than a long list of routine cases. Limit access to the people who need the record, and review permissions when a role changes."]},{"heading":"Reconcile after the transfer posts","paragraphs":["a trust-to-operating transfer works only when the team can connect a request to its source and its owner. The process starts when the firm believes fees have been earned, and it should leave a dated record in the trust ledger and billing system. The billing assistant gathers the client authorization and the invoice and payment history, then checks the trust ledger balance against the earned fee calculation. Reconcile the ledger after the transfer posts and keep the confirmation with the request.","Set a review cadence of each transfer request and keep the definitions stable. Review the evidence with the responsible attorney and finance owner and the person who maintains the transfer review packet. Choose one change that would prevent the most rework, and give it a named owner and a date. The next review should test whether that change worked without adding hidden exceptions."]}],"faq":[{"q":"Who owns a trust-to-operating transfer?","a":"The responsible attorney and finance owner owns the decision to authorize the transfer; the billing assistant prepares the evidence and flags exceptions."},{"q":"What proves that the transfer review packet is complete?","a":"A reviewer can see the client authorization, the approval, the effective date, and the next action without asking the preparer."},{"q":"When should the team review this?","a":"Review it each transfer request and after any change to the client requirement or the billing system."}],"publishedAt":"2026-11-09"},{"slug":"build-a-client-portal-rejection-log-reviewers-can-scan","title":"Build a client portal rejection log reviewers can scan","description":"A rejection log that records the portal code, invoice line, reviewer note, owner, and resubmission deadline in one reviewable queue.","category":"E-billing","readTime":"9 min read","thumbnail":"/thumbnails/november-09/build-a-client-portal-rejection-log-reviewers-can-scan.webp","internalService":"/services/e-billing-support","internalSibling":"/blog/write-a-billing-continuity-plan-for-a-sudden-staff-absence","source":{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},"sections":[{"heading":"Capture the rejection at the moment it appears","paragraphs":["a client portal invoice rejection works only when the team can connect a request to its source and its owner. The process starts when the portal rejects an invoice or line item, and it should leave a dated record in the e-billing portal and billing system. The e-billing assistant gathers the portal rejection message and the rejected invoice line, then checks the client billing guideline against the resubmission deadline. A portal rejection is easiest to explain while the message and the invoice line are still in front of the reviewer.","A useful the rejection log answers four questions in one place. It shows what changed, who approved the change, when it took effect, and which records depend on it. Those answers belong beside the case rather than in a separate email thread. A reviewer should reconstruct the path without asking the preparer for context."]},{"heading":"Record the portal code and the reviewer note","paragraphs":["a client portal invoice rejection works only when the team can connect a request to its source and its owner. The process starts when the portal rejects an invoice or line item, and it should leave a dated record in the e-billing portal and billing system. The e-billing assistant gathers the portal rejection message and the rejected invoice line, then checks the client billing guideline against the resubmission deadline. Record the portal code exactly as it appears, then add a plain-language note about the actual problem.","The approval chain matters as much as the final value. Name who prepared the case, who reviewed it, and who had authority to approve the decision to resubmit or appeal the rejection. Keep the approval date next to the value so a later reader can see when the state changed. A value without an approval trail is an assertion, not a controlled record."]},{"heading":"Link every rejection to the invoice line","paragraphs":["a client portal invoice rejection works only when the team can connect a request to its source and its owner. The process starts when the portal rejects an invoice or line item, and it should leave a dated record in the e-billing portal and billing system. The e-billing assistant gathers the portal rejection message and the rejected invoice line, then checks the client billing guideline against the resubmission deadline. Every rejection needs a link to the invoice line so the correction can be checked against the source.","Keep a short list of exception types and the evidence each one requires. A missing document, a client instruction, and an internal correction should not share one code. The code should point to the fix, whether that is a source request, a template change, or an approval step. When the same exception repeats, treat it as a process gap rather than a one-off mistake."]},{"heading":"Separate format errors from substantive disputes","paragraphs":["a client portal invoice rejection works only when the team can connect a request to its source and its owner. The process starts when the portal rejects an invoice or line item, and it should leave a dated record in the e-billing portal and billing system. The e-billing assistant gathers the portal rejection message and the rejected invoice line, then checks the client billing guideline against the resubmission deadline. A format error and a fee dispute should not share one queue path, because they need different owners.","Define the fields before the first entry and keep them stable. Use one field for the source, one for the decision, one for the effective date, and one for the next action in the e-billing portal and billing system. Free-text notes are useful for context but should not be the only place where an owner or deadline appears. Stable fields make the queue sortable and let a reviewer find the cases that need attention."]},{"heading":"Track the resubmission deadline and owner","paragraphs":["a client portal invoice rejection works only when the team can connect a request to its source and its owner. The process starts when the portal rejects an invoice or line item, and it should leave a dated record in the e-billing portal and billing system. The e-billing assistant gathers the portal rejection message and the rejected invoice line, then checks the client billing guideline against the resubmission deadline. The resubmission deadline and the owner belong on the same row as the rejection code.","Set a response rule for each type of wait. A missing receipt may allow a short grace period, while a missing client authorization should pause the charge. Record the rule and the date the case last changed so a reviewer can see whether it is moving. Do not close a case just because the deadline passed, because an unresolved exception should stay visible."]},{"heading":"Show which corrections require partner approval","paragraphs":["a client portal invoice rejection works only when the team can connect a request to its source and its owner. The process starts when the portal rejects an invoice or line item, and it should leave a dated record in the e-billing portal and billing system. The e-billing assistant gathers the portal rejection message and the rejected invoice line, then checks the client billing guideline against the resubmission deadline. A correction that changes a fee needs partner approval before the resubmission is sent.","Run the test on two different matter types before adopting the template. A routine matter and an exception case should both produce a readable record, even if they need different evidence. Keep the test notes with the template version so the change is traceable. A tool that has never been used by a second person is still a draft."]},{"heading":"Review rejection patterns with the client","paragraphs":["a client portal invoice rejection works only when the team can connect a request to its source and its owner. The process starts when the portal rejects an invoice or line item, and it should leave a dated record in the e-billing portal and billing system. The e-billing assistant gathers the portal rejection message and the rejected invoice line, then checks the client billing guideline against the resubmission deadline. Review the log with the client contact when the same code appears across several invoices.","Give each audience the view it needs to act. The e-billing manager needs the exception and the decision, while the billing team needs the owner and the next action. A partner summary should show exposure and timing rather than a long list of routine cases. Limit access to the people who need the record, and review permissions when a role changes."]},{"heading":"Keep the log aligned with the billing system","paragraphs":["a client portal invoice rejection works only when the team can connect a request to its source and its owner. The process starts when the portal rejects an invoice or line item, and it should leave a dated record in the e-billing portal and billing system. The e-billing assistant gathers the portal rejection message and the rejected invoice line, then checks the client billing guideline against the resubmission deadline. Reconcile the log with the billing system after each submission window so closed items do not linger.","Set a review cadence of daily during submission windows and keep the definitions stable. Review the evidence with the e-billing manager and the person who maintains the rejection log. Choose one change that would prevent the most rework, and give it a named owner and a date. The next review should test whether that change worked without adding hidden exceptions."]}],"faq":[{"q":"Who owns a client portal invoice rejection?","a":"The e-billing manager owns the decision to resubmit or appeal the rejection; the e-billing assistant prepares the evidence and flags exceptions."},{"q":"What proves that the rejection log is complete?","a":"A reviewer can see the portal rejection message, the approval, the effective date, and the next action without asking the preparer."},{"q":"When should the team review this?","a":"Review it daily during submission windows and after any change to the client requirement or the billing system."}],"publishedAt":"2026-11-09"},{"slug":"write-a-billing-continuity-plan-for-a-sudden-staff-absence","title":"Write a billing continuity plan for a sudden staff absence","description":"A continuity plan that names the queues, access, backups, and handoff evidence needed when a billing specialist is suddenly unavailable.","category":"Role design","readTime":"9 min read","thumbnail":"/thumbnails/november-09/write-a-billing-continuity-plan-for-a-sudden-staff-absence.webp","internalService":"/services/billing-reporting-support","internalSibling":"/blog/build-a-phase-level-budget-alert-routine-partners-will-use","source":{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},"sections":[{"heading":"Name the queues that cannot pause","paragraphs":["billing continuity during an absence works only when the team can connect a request to its source and its owner. The process starts when a billing specialist is unexpectedly unavailable, and it should leave a dated record in the billing queue and document systems. The billing team lead gathers the queue ownership list and the access recovery steps, then checks the coverage roster against the open-item handoff. A continuity plan starts with the queues that cannot wait for a replacement to be hired.","A useful the continuity plan answers four questions in one place. It shows what changed, who approved the change, when it took effect, and which records depend on it. Those answers belong beside the case rather than in a separate email thread. A reviewer should reconstruct the path without asking the preparer for context."]},{"heading":"Document access and recovery steps","paragraphs":["billing continuity during an absence works only when the team can connect a request to its source and its owner. The process starts when a billing specialist is unexpectedly unavailable, and it should leave a dated record in the billing queue and document systems. The billing team lead gathers the queue ownership list and the access recovery steps, then checks the coverage roster against the open-item handoff. Document how a backup gets access to the billing system, the shared inbox, and the document folders.","The approval chain matters as much as the final value. Name who prepared the case, who reviewed it, and who had authority to approve the decision to activate the coverage roster. Keep the approval date next to the value so a later reader can see when the state changed. A value without an approval trail is an assertion, not a controlled record."]},{"heading":"Create a coverage roster with real backups","paragraphs":["billing continuity during an absence works only when the team can connect a request to its source and its owner. The process starts when a billing specialist is unexpectedly unavailable, and it should leave a dated record in the billing queue and document systems. The billing team lead gathers the queue ownership list and the access recovery steps, then checks the coverage roster against the open-item handoff. A coverage roster should name a real person for each queue, not a team mailbox.","Keep a short list of exception types and the evidence each one requires. A missing document, a client instruction, and an internal correction should not share one code. The code should point to the fix, whether that is a source request, a template change, or an approval step. When the same exception repeats, treat it as a process gap rather than a one-off mistake."]},{"heading":"Prepare a shift handoff template","paragraphs":["billing continuity during an absence works only when the team can connect a request to its source and its owner. The process starts when a billing specialist is unexpectedly unavailable, and it should leave a dated record in the billing queue and document systems. The billing team lead gathers the queue ownership list and the access recovery steps, then checks the coverage roster against the open-item handoff. The handoff template should show the open item, the next action, the deadline, and the evidence.","Define the fields before the first entry and keep them stable. Use one field for the source, one for the decision, one for the effective date, and one for the next action in the billing queue and document systems. Free-text notes are useful for context but should not be the only place where an owner or deadline appears. Stable fields make the queue sortable and let a reviewer find the cases that need attention."]},{"heading":"Test the plan with a short absence","paragraphs":["billing continuity during an absence works only when the team can connect a request to its source and its owner. The process starts when a billing specialist is unexpectedly unavailable, and it should leave a dated record in the billing queue and document systems. The billing team lead gathers the queue ownership list and the access recovery steps, then checks the coverage roster against the open-item handoff. Test the plan with a planned half-day absence before a real emergency tests it for you.","Set a response rule for each type of wait. A missing receipt may allow a short grace period, while a missing client authorization should pause the charge. Record the rule and the date the case last changed so a reviewer can see whether it is moving. Do not close a case just because the deadline passed, because an unresolved exception should stay visible."]},{"heading":"Protect client communication during a gap","paragraphs":["billing continuity during an absence works only when the team can connect a request to its source and its owner. The process starts when a billing specialist is unexpectedly unavailable, and it should leave a dated record in the billing queue and document systems. The billing team lead gathers the queue ownership list and the access recovery steps, then checks the coverage roster against the open-item handoff. Client communication needs an approved owner during a gap so messages do not go unanswered.","Run the test on two different matter types before adopting the template. A routine matter and an exception case should both produce a readable record, even if they need different evidence. Keep the test notes with the template version so the change is traceable. A tool that has never been used by a second person is still a draft."]},{"heading":"Review what failed after coverage ends","paragraphs":["billing continuity during an absence works only when the team can connect a request to its source and its owner. The process starts when a billing specialist is unexpectedly unavailable, and it should leave a dated record in the billing queue and document systems. The billing team lead gathers the queue ownership list and the access recovery steps, then checks the coverage roster against the open-item handoff. After coverage ends, record what failed and which step caused the most delay.","Give each audience the view it needs to act. The billing manager needs the exception and the decision, while the billing team needs the owner and the next action. A partner summary should show exposure and timing rather than a long list of routine cases. Limit access to the people who need the record, and review permissions when a role changes."]},{"heading":"Update the plan on a fixed schedule","paragraphs":["billing continuity during an absence works only when the team can connect a request to its source and its owner. The process starts when a billing specialist is unexpectedly unavailable, and it should leave a dated record in the billing queue and document systems. The billing team lead gathers the queue ownership list and the access recovery steps, then checks the coverage roster against the open-item handoff. Review the plan on a fixed schedule and whenever a role or system changes.","Set a review cadence of each absence and quarterly drill and keep the definitions stable. Review the evidence with the billing manager and the person who maintains the continuity plan. Choose one change that would prevent the most rework, and give it a named owner and a date. The next review should test whether that change worked without adding hidden exceptions."]}],"faq":[{"q":"Who owns billing continuity during an absence?","a":"The billing manager owns the decision to activate the coverage roster; the billing team lead prepares the evidence and flags exceptions."},{"q":"What proves that the continuity plan is complete?","a":"A reviewer can see the queue ownership list, the approval, the effective date, and the next action without asking the preparer."},{"q":"When should the team review this?","a":"Review it each absence and quarterly drill and after any change to the client requirement or the billing system."}],"publishedAt":"2026-11-09"},{"slug":"build-a-phase-level-budget-alert-routine-partners-will-use","title":"Build a phase-level budget alert routine partners will use","description":"A budget alert routine that compares approved phase amounts with unbilled work and gives the partner a short, evidence-based decision brief.","category":"Budgets","readTime":"9 min read","thumbnail":"/thumbnails/november-09/build-a-phase-level-budget-alert-routine-partners-will-use.webp","internalService":"/services/prebill-preparation","internalSibling":"/blog/prepare-a-year-end-billing-close-checklist-for-the-whole-team","source":{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},"sections":[{"heading":"Build alerts from the approved phase budget","paragraphs":["a phase-level budget alert works only when the team can connect a request to its source and its owner. The process starts when unbilled work approaches the approved phase amount, and it should leave a dated record in the time and billing system. The billing assistant gathers the approved phase budget and the unbilled time total, then checks the planned remaining work against the prior client communication. A phase alert is useful only when it compares the approved amount with the work that is already committed.","A useful the alert routine answers four questions in one place. It shows what changed, who approved the change, when it took effect, and which records depend on it. Those answers belong beside the case rather than in a separate email thread. A reviewer should reconstruct the path without asking the preparer for context."]},{"heading":"Choose thresholds that prompt a decision","paragraphs":["a phase-level budget alert works only when the team can connect a request to its source and its owner. The process starts when unbilled work approaches the approved phase amount, and it should leave a dated record in the time and billing system. The billing assistant gathers the approved phase budget and the unbilled time total, then checks the planned remaining work against the prior client communication. Choose a warning threshold and a decision threshold instead of one alarm that fires too often.","The approval chain matters as much as the final value. Name who prepared the case, who reviewed it, and who had authority to approve the decision to continue, revise, or pause the phase. Keep the approval date next to the value so a later reader can see when the state changed. A value without an approval trail is an assertion, not a controlled record."]},{"heading":"Include unbilled time and planned work","paragraphs":["a phase-level budget alert works only when the team can connect a request to its source and its owner. The process starts when unbilled work approaches the approved phase amount, and it should leave a dated record in the time and billing system. The billing assistant gathers the approved phase budget and the unbilled time total, then checks the planned remaining work against the prior client communication. Include unbilled time and planned remaining work so the alert reflects the full phase obligation.","Keep a short list of exception types and the evidence each one requires. A missing document, a client instruction, and an internal correction should not share one code. The code should point to the fix, whether that is a source request, a template change, or an approval step. When the same exception repeats, treat it as a process gap rather than a one-off mistake."]},{"heading":"Route the alert to the budget owner","paragraphs":["a phase-level budget alert works only when the team can connect a request to its source and its owner. The process starts when unbilled work approaches the approved phase amount, and it should leave a dated record in the time and billing system. The billing assistant gathers the approved phase budget and the unbilled time total, then checks the planned remaining work against the prior client communication. Route the alert to the budget owner who can actually change the staffing or the scope.","Define the fields before the first entry and keep them stable. Use one field for the source, one for the decision, one for the effective date, and one for the next action in the time and billing system. Free-text notes are useful for context but should not be the only place where an owner or deadline appears. Stable fields make the queue sortable and let a reviewer find the cases that need attention."]},{"heading":"Give the partner a short decision brief","paragraphs":["a phase-level budget alert works only when the team can connect a request to its source and its owner. The process starts when unbilled work approaches the approved phase amount, and it should leave a dated record in the time and billing system. The billing assistant gathers the approved phase budget and the unbilled time total, then checks the planned remaining work against the prior client communication. The brief should show the amount, the variance, the cause, and the decision needed in one screen.","Set a response rule for each type of wait. A missing receipt may allow a short grace period, while a missing client authorization should pause the charge. Record the rule and the date the case last changed so a reviewer can see whether it is moving. Do not close a case just because the deadline passed, because an unresolved exception should stay visible."]},{"heading":"Record the response and the revised plan","paragraphs":["a phase-level budget alert works only when the team can connect a request to its source and its owner. The process starts when unbilled work approaches the approved phase amount, and it should leave a dated record in the time and billing system. The billing assistant gathers the approved phase budget and the unbilled time total, then checks the planned remaining work against the prior client communication. Record the partner's response and the revised plan so the next alert starts from the new baseline.","Run the test on two different matter types before adopting the template. A routine matter and an exception case should both produce a readable record, even if they need different evidence. Keep the test notes with the template version so the change is traceable. A tool that has never been used by a second person is still a draft."]},{"heading":"Avoid alert fatigue with a tiered rule","paragraphs":["a phase-level budget alert works only when the team can connect a request to its source and its owner. The process starts when unbilled work approaches the approved phase amount, and it should leave a dated record in the time and billing system. The billing assistant gathers the approved phase budget and the unbilled time total, then checks the planned remaining work against the prior client communication. Use a tiered rule so routine movement does not train the partner to ignore the alert.","Give each audience the view it needs to act. The budget owner or partner needs the exception and the decision, while the billing team needs the owner and the next action. A partner summary should show exposure and timing rather than a long list of routine cases. Limit access to the people who need the record, and review permissions when a role changes."]},{"heading":"Review alert accuracy after the invoice","paragraphs":["a phase-level budget alert works only when the team can connect a request to its source and its owner. The process starts when unbilled work approaches the approved phase amount, and it should leave a dated record in the time and billing system. The billing assistant gathers the approved phase budget and the unbilled time total, then checks the planned remaining work against the prior client communication. Compare the alert with the final invoice and adjust the threshold if it was consistently early or late.","Set a review cadence of weekly during active phases and keep the definitions stable. Review the evidence with the budget owner or partner and the person who maintains the alert routine. Choose one change that would prevent the most rework, and give it a named owner and a date. The next review should test whether that change worked without adding hidden exceptions."]}],"faq":[{"q":"Who owns a phase-level budget alert?","a":"The budget owner or partner owns the decision to continue, revise, or pause the phase; the billing assistant prepares the evidence and flags exceptions."},{"q":"What proves that the alert routine is complete?","a":"A reviewer can see the approved phase budget, the approval, the effective date, and the next action without asking the preparer."},{"q":"When should the team review this?","a":"Review it weekly during active phases and after any change to the client requirement or the billing system."}],"publishedAt":"2026-11-09"},{"slug":"prepare-a-year-end-billing-close-checklist-for-the-whole-team","title":"Prepare a year-end billing close checklist for the whole team","description":"A year-end close checklist that reconciles unbilled work, rejections, write-offs, trust balances, and client communication before sign-off.","category":"Billing operations","readTime":"9 min read","thumbnail":"/thumbnails/november-09/prepare-a-year-end-billing-close-checklist-for-the-whole-team.webp","internalService":"/services/billing-reporting-support","internalSibling":"/blog/build-a-rate-increase-notice-tracker-the-billing-team-can-trust","source":{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},"sections":[{"heading":"Set the cut-off before calendar pressure","paragraphs":["the year-end billing close works only when the team can connect a request to its source and its owner. The process starts when the firm sets its year-end cut-off, and it should leave a dated record in the billing, trust, and accounting systems. The billing team gathers the unbilled time report and the open rejection list, then checks the write-off and credit log against the trust reconciliation. A year-end close needs a cut-off that is communicated before the last week of the year.","A useful the close checklist answers four questions in one place. It shows what changed, who approved the change, when it took effect, and which records depend on it. Those answers belong beside the case rather than in a separate email thread. A reviewer should reconstruct the path without asking the preparer for context."]},{"heading":"Reconcile unbilled time and expenses","paragraphs":["the year-end billing close works only when the team can connect a request to its source and its owner. The process starts when the firm sets its year-end cut-off, and it should leave a dated record in the billing, trust, and accounting systems. The billing team gathers the unbilled time report and the open rejection list, then checks the write-off and credit log against the trust reconciliation. Reconcile unbilled time and expenses against the matter records before anyone prepares final invoices.","The approval chain matters as much as the final value. Name who prepared the case, who reviewed it, and who had authority to approve the decision to sign off the close. Keep the approval date next to the value so a later reader can see when the state changed. A value without an approval trail is an assertion, not a controlled record."]},{"heading":"Clear rejections and pending appeals","paragraphs":["the year-end billing close works only when the team can connect a request to its source and its owner. The process starts when the firm sets its year-end cut-off, and it should leave a dated record in the billing, trust, and accounting systems. The billing team gathers the unbilled time report and the open rejection list, then checks the write-off and credit log against the trust reconciliation. Open rejections and appeals need a decision or a documented carry-forward date.","Keep a short list of exception types and the evidence each one requires. A missing document, a client instruction, and an internal correction should not share one code. The code should point to the fix, whether that is a source request, a template change, or an approval step. When the same exception repeats, treat it as a process gap rather than a one-off mistake."]},{"heading":"Review write-offs and credit balances","paragraphs":["the year-end billing close works only when the team can connect a request to its source and its owner. The process starts when the firm sets its year-end cut-off, and it should leave a dated record in the billing, trust, and accounting systems. The billing team gathers the unbilled time report and the open rejection list, then checks the write-off and credit log against the trust reconciliation. Review write-offs and credit balances for missing approval and for duplicates across matters.","Define the fields before the first entry and keep them stable. Use one field for the source, one for the decision, one for the effective date, and one for the next action in the billing, trust, and accounting systems. Free-text notes are useful for context but should not be the only place where an owner or deadline appears. Stable fields make the queue sortable and let a reviewer find the cases that need attention."]},{"heading":"Confirm trust and operating account status","paragraphs":["the year-end billing close works only when the team can connect a request to its source and its owner. The process starts when the firm sets its year-end cut-off, and it should leave a dated record in the billing, trust, and accounting systems. The billing team gathers the unbilled time report and the open rejection list, then checks the write-off and credit log against the trust reconciliation. Confirm that the trust reconciliation and the operating balance agree with the accounting records.","Set a response rule for each type of wait. A missing receipt may allow a short grace period, while a missing client authorization should pause the charge. Record the rule and the date the case last changed so a reviewer can see whether it is moving. Do not close a case just because the deadline passed, because an unresolved exception should stay visible."]},{"heading":"Prepare client communication for open items","paragraphs":["the year-end billing close works only when the team can connect a request to its source and its owner. The process starts when the firm sets its year-end cut-off, and it should leave a dated record in the billing, trust, and accounting systems. The billing team gathers the unbilled time report and the open rejection list, then checks the write-off and credit log against the trust reconciliation. Client communication about open items should go out before the cut-off, not after the invoice is final.","Run the test on two different matter types before adopting the template. A routine matter and an exception case should both produce a readable record, even if they need different evidence. Keep the test notes with the template version so the change is traceable. A tool that has never been used by a second person is still a draft."]},{"heading":"Assign owners for each closing task","paragraphs":["the year-end billing close works only when the team can connect a request to its source and its owner. The process starts when the firm sets its year-end cut-off, and it should leave a dated record in the billing, trust, and accounting systems. The billing team gathers the unbilled time report and the open rejection list, then checks the write-off and credit log against the trust reconciliation. Every closing task needs a named owner, a due date, and the evidence that will close it.","Give each audience the view it needs to act. The billing manager and finance owner needs the exception and the decision, while the billing team needs the owner and the next action. A partner summary should show exposure and timing rather than a long list of routine cases. Limit access to the people who need the record, and review permissions when a role changes."]},{"heading":"Run a final evidence review before sign-off","paragraphs":["the year-end billing close works only when the team can connect a request to its source and its owner. The process starts when the firm sets its year-end cut-off, and it should leave a dated record in the billing, trust, and accounting systems. The billing team gathers the unbilled time report and the open rejection list, then checks the write-off and credit log against the trust reconciliation. Run a final evidence review before sign-off and record any item that remains open.","Set a review cadence of annually with a mid-cycle check and keep the definitions stable. Review the evidence with the billing manager and finance owner and the person who maintains the close checklist. Choose one change that would prevent the most rework, and give it a named owner and a date. The next review should test whether that change worked without adding hidden exceptions."]}],"faq":[{"q":"Who owns the year-end billing close?","a":"The billing manager and finance owner owns the decision to sign off the close; the billing team prepares the evidence and flags exceptions."},{"q":"What proves that the close checklist is complete?","a":"A reviewer can see the unbilled time report, the approval, the effective date, and the next action without asking the preparer."},{"q":"When should the team review this?","a":"Review it annually with a mid-cycle check and after any change to the client requirement or the billing system."}],"publishedAt":"2026-11-09"}];

export const november09ResearchPosts: readonly ResearchPost[] = [{"slug":"how-often-do-rate-increase-notices-arrive-after-the-effective-date","title":"How often do rate increase notices arrive after the effective date?","summary":"A timing study that compares each approved rate change with the client notice date and reports how much of the change had to be handled after the fact.","cluster":"Rate management","finding":"Late notice is a workflow measure, not a pricing judgment, and it shows where the approval, client communication, and billing setup steps lose time.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how often a rate increase notice reaches the billing team after the effective date. The unit is a rate notice record, and the purpose is to measure the days between the effective date and the client notice without turning the result into a performance judgment. The study is limited to every approved rate change in the period and uses the definitions the firm already maintains. The question is narrow on purpose, because a late notice can be counted without judging whether the new rate was correct.","Scope the study to one billing period and the rate changes that were approved for active clients. Include the cases that were approved, rejected, and still open so the denominator reflects the full workload. Exclude records that do not meet the event definition, and keep the exclusion list with the study file. State the period, the systems, and the owner so the result is not generalized beyond the sample."]},{"heading":"Defining the event","paragraphs":["Define a late rate notice before collecting any data. The definition should say what counts, what does not, and which source proves the event occurred. Write two examples and one boundary case so two reviewers apply the same rule. A notice counts as late when the client communication date is later than the effective date recorded in the rate table.","Distinguish a late rate notice from a related but different case. A follow-up, a correction, and a duplicate can look similar in the queue but point to different fixes. Code the related cases separately rather than forcing them into the main category. The separation keeps the report honest about what was measured."]},{"heading":"Population and denominator","paragraphs":["The population is every approved rate change in the period. Report the number of records in the population, the number excluded, and the number in the final sample. Track the records that arrive late so the study does not silently drop them. The population should include changes that were later deferred, because dropping them would hide the cases that caused the most rework.","Use one consistent unit for the denominator. Count a rate notice record rather than messages, lines, or people unless the study is explicitly about that unit. If a record contains several events, split it or state that it is treated as one. Consistency matters more than precision when the source data is imperfect."]},{"heading":"Evidence sources","paragraphs":["Use the signed rate notice, the client communication record, and the effective date field as the primary evidence. Compare the source with the field in the rate table and client notice file and record the date each was observed. If the first invoice after the change is missing, mark the record incomplete instead of inferring the value. A notice record is usable only when the rate table, the client message, and the invoice line can be matched.","Keep a short evidence hierarchy so reviewers know what to trust first for rate notice timing. A signed client document is stronger than a summary written by the person who handled the case. A contemporaneous note is stronger than a later recollection, and the report should say which was used. Record the evidence type so the analysis can separate a documentation problem from a process problem."]},{"heading":"Sampling","paragraphs":["Sample across the groups that could change the result. Include different clients, matter types, staff members, and volume bands where the data allows. Draw the sample before reading the outcomes so the selection is not biased toward the obvious cases. Sample across clients that receive rate changes at different times so one annual cycle does not dominate the result.","If the population is small, review every record and extend the period rather than lowering the evidence standard for rate notice timing. Track the records that are still open at the end of the window and report them separately. Do not drop an inconvenient case without a documented exclusion reason. A reproducible sample is more useful than a large one with unclear boundaries."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code the primary cause, the stage where it was discovered, and any secondary factor that changed the outcome. Add an unknown category for cases the evidence cannot resolve. Code each late notice by the stage where it lost time, such as approval, drafting, delivery, or billing setup.","Have a second reviewer code a sample of a late rate notice and compare the results. Resolve disagreements by returning to the source rather than by majority vote. Report the agreement rate and revise any code that is used inconsistently. If the reviewers cannot agree on the definition, stop and fix the definition before continuing."]},{"heading":"Measuring time","paragraphs":["Measure the active time or the elapsed time that matches the question. Use a short log completed at the moment of the work, and separate search, decision, and communication time for a late rate notice. Report the median and the range rather than a single average. Measure the elapsed days and the active follow-up time separately, because waiting and work are different problems.","Do not convert time to a dollar figure without an approved labor rate for rate notice timing. The study measures effort and delay, not price, unless the firm has explicitly asked for a cost estimate. Keep the raw time entries with the analysis file so a reviewer can check the calculation. A precise number built on rounded guesses is less useful than a range with a clear source."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall rate, the group results, and the number behind each figure. Show the share that reached a client-facing stage, because late discovery usually costs more than early detection. Compare only groups with similar scope and duration. Report the late share beside the median delay and the number of invoices already issued at the old rate.","Give the reader one table or chart that answers the main question about rate notice timing and put the detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the main pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["Source records are often incomplete, and a missing record is not proof that the event did not happen. Report the completeness of the evidence before drawing a conclusion, and name the owner of each source. Small samples, changing guidelines, and reviewer disagreement can all limit interpretation. A missing notice is a limit of the record, not proof that the client was never told.","Avoid comparing groups that differ in complexity or client requirements for rate notice timing. A long matter has more opportunity for an event, and a fixed-fee matter may have none by design. Describe the context beside the rate and avoid ranking individuals. The purpose is to improve the process, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the sample and the evidence in a controlled folder with access limited to the study team. Remove client names, amounts, and matter details from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the specific amount. Keep client names and rate amounts out of the analysis file, and use a role label when an example is shared.","Do not circulate a person-level or client-level list about rate notice timing outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the billing system and to quoted client messages. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common cause in the data. If the gap is a missing field, add it to the template; if it is a late approval, add a named owner and a deadline. Test the change on a defined group and compare the same measures with the baseline for rate notice timing. The first repair should match the stage with the most late notices, not the stage that is easiest to blame.","A lower rate is not the only useful result for rate notice timing. Faster detection, clearer evidence, and fewer repeated questions can all improve the process even when the count stays similar. Report both the direct result and the service result, and keep the definitions stable. Stop the change if it shifts the work into a private channel where it cannot be reviewed."]},{"heading":"Review cadence","paragraphs":["Repeat the study on each rate cycle and after any major change to the template, system, or client requirement. Keep the definitions and the unit stable so the comparison is meaningful. Report the records that were excluded or still open beside the main rate. Review the result after each rate cycle and keep the late definition stable so two periods can be compared.","Review the result with billing manager and the people who maintain the record for rate notice timing. Ask which fix is easiest to sustain and which gap causes the most rework. Set one change and a follow-up date, then check whether the change held. The next study should test the repair, not just repeat the same count."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-09","thumbnail":"/thumbnails/november-09/how-often-do-rate-increase-notices-arrive-after-the-effective-date.webp"},{"slug":"what-share-of-e-billing-rejections-trace-to-a-matter-setup-field","title":"What share of e-billing rejections trace to a matter setup field?","summary":"A coding study that traces each rejection back to the matter setup field, intake source, and reviewer who could have caught the problem earlier.","cluster":"E-billing","finding":"A rejection is more useful when it is coded by origin field than by portal code, because the origin points to the intake or setup step that needs the repair.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks what share of e-billing rejections trace to a matter setup field. The unit is a rejected invoice or line item, and the purpose is to measure the share of rejections whose primary cause is a setup field without turning the result into a performance judgment. The study is limited to every rejection received in the period and uses the definitions the firm already maintains. A rejection can look like a formatting problem while the real cause is a missing matter identifier or a wrong billing entity.","Scope the study to the client portals and matters that submitted at least one invoice in the period. Include the cases that were approved, rejected, and still open so the denominator reflects the full workload. Exclude records that do not meet the event definition, and keep the exclusion list with the study file. State the period, the systems, and the owner so the result is not generalized beyond the sample."]},{"heading":"Defining the event","paragraphs":["Define a setup-related rejection before collecting any data. The definition should say what counts, what does not, and which source proves the event occurred. Write two examples and one boundary case so two reviewers apply the same rule. The unit is the rejected invoice or line, because one invoice may produce several independent rejection messages.","Distinguish a setup-related rejection from a related but different case. A follow-up, a correction, and a duplicate can look similar in the queue but point to different fixes. Code the related cases separately rather than forcing them into the main category. The separation keeps the report honest about what was measured."]},{"heading":"Population and denominator","paragraphs":["The population is every rejection received in the period. Report the number of records in the population, the number excluded, and the number in the final sample. Track the records that arrive late so the study does not silently drop them. The population should include rejections that were later accepted, because the correction history is where the setup cause becomes visible.","Use one consistent unit for the denominator. Count a rejected invoice or line item rather than messages, lines, or people unless the study is explicitly about that unit. If a record contains several events, split it or state that it is treated as one. Consistency matters more than precision when the source data is imperfect."]},{"heading":"Evidence sources","paragraphs":["Use the portal rejection message, the matter setup record, and the client billing guideline as the primary evidence. Compare the source with the field in the e-billing portal and matter record and record the date each was observed. If the resubmission history is missing, mark the record incomplete instead of inferring the value. The portal message, the matter record, and the resubmission note should be read together before a cause is coded.","Keep a short evidence hierarchy so reviewers know what to trust first for setup-related rejections. A signed client document is stronger than a summary written by the person who handled the case. A contemporaneous note is stronger than a later recollection, and the report should say which was used. Record the evidence type so the analysis can separate a documentation problem from a process problem."]},{"heading":"Sampling","paragraphs":["Sample across the groups that could change the result. Include different clients, matter types, staff members, and volume bands where the data allows. Draw the sample before reading the outcomes so the selection is not biased toward the obvious cases. Sample across portals and client types so the result is not driven by one client's submission rules.","If the population is small, review every record and extend the period rather than lowering the evidence standard for setup-related rejections. Track the records that are still open at the end of the window and report them separately. Do not drop an inconvenient case without a documented exclusion reason. A reproducible sample is more useful than a large one with unclear boundaries."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code the primary cause, the stage where it was discovered, and any secondary factor that changed the outcome. Add an unknown category for cases the evidence cannot resolve. Code the field that should have been correct at setup, the stage where it was discovered, and the person who could have caught it.","Have a second reviewer code a sample of a setup-related rejection and compare the results. Resolve disagreements by returning to the source rather than by majority vote. Report the agreement rate and revise any code that is used inconsistently. If the reviewers cannot agree on the definition, stop and fix the definition before continuing."]},{"heading":"Measuring time","paragraphs":["Measure the active time or the elapsed time that matches the question. Use a short log completed at the moment of the work, and separate search, decision, and communication time for a setup-related rejection. Report the median and the range rather than a single average. Measure the time from rejection to resubmission and the number of resubmission attempts for each case.","Do not convert time to a dollar figure without an approved labor rate for setup-related rejections. The study measures effort and delay, not price, unless the firm has explicitly asked for a cost estimate. Keep the raw time entries with the analysis file so a reviewer can check the calculation. A precise number built on rounded guesses is less useful than a range with a clear source."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall rate, the group results, and the number behind each figure. Show the share that reached a client-facing stage, because late discovery usually costs more than early detection. Compare only groups with similar scope and duration. Report the setup share beside the total rejection count and the number of invoices in the population.","Give the reader one table or chart that answers the main question about setup-related rejections and put the detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the main pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["Source records are often incomplete, and a missing record is not proof that the event did not happen. Report the completeness of the evidence before drawing a conclusion, and name the owner of each source. Small samples, changing guidelines, and reviewer disagreement can all limit interpretation. A rejection with no clear cause belongs in the unknown category and should not be assigned to setup by default.","Avoid comparing groups that differ in complexity or client requirements for setup-related rejections. A long matter has more opportunity for an event, and a fixed-fee matter may have none by design. Describe the context beside the rate and avoid ranking individuals. The purpose is to improve the process, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the sample and the evidence in a controlled folder with access limited to the study team. Remove client names, amounts, and matter details from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the specific amount. Remove client names and matter details from the coding sheet and keep the portal evidence in the controlled folder.","Do not circulate a person-level or client-level list about setup-related rejections outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the billing system and to quoted client messages. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common cause in the data. If the gap is a missing field, add it to the template; if it is a late approval, add a named owner and a deadline. Test the change on a defined group and compare the same measures with the baseline for setup-related rejections. If one setup field dominates, repair the intake form or the client onboarding check before adding more reviewer training.","A lower rate is not the only useful result for setup-related rejections. Faster detection, clearer evidence, and fewer repeated questions can all improve the process even when the count stays similar. Report both the direct result and the service result, and keep the definitions stable. Stop the change if it shifts the work into a private channel where it cannot be reviewed."]},{"heading":"Review cadence","paragraphs":["Repeat the study on each submission window and after any major change to the template, system, or client requirement. Keep the definitions and the unit stable so the comparison is meaningful. Report the records that were excluded or still open beside the main rate. Review the result after each portal change and keep the field definitions stable so the next count is comparable.","Review the result with e-billing manager and the people who maintain the record for setup-related rejections. Ask which fix is easiest to sustain and which gap causes the most rework. Set one change and a follow-up date, then check whether the change held. The next study should test the repair, not just repeat the same count."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-09","thumbnail":"/thumbnails/november-09/what-share-of-e-billing-rejections-trace-to-a-matter-setup-field.webp"},{"slug":"how-much-invoice-review-time-goes-to-resolving-disbursement-questions","title":"How much invoice review time goes to resolving disbursement questions?","summary":"A time study that measures the reviewer effort spent finding receipts, confirming client authorization, and correcting cost lines before an invoice is released.","cluster":"Disbursements","finding":"Disbursement questions consume review time in small bursts, and separating search time from decision time shows whether the fix belongs to filing or to the approval rule.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how much invoice review time goes to resolving disbursement questions. The unit is a reviewer handling event, and the purpose is to measure the active minutes per disbursement question without turning the result into a performance judgment. The study is limited to every invoice review session in the period and uses the definitions the firm already maintains. A disbursement question can take two minutes to answer and twenty minutes to find, so the study should separate search from decision.","Scope the study to the invoices reviewed by the billing team during the period. Include the cases that were approved, rejected, and still open so the denominator reflects the full workload. Exclude records that do not meet the event definition, and keep the exclusion list with the study file. State the period, the systems, and the owner so the result is not generalized beyond the sample."]},{"heading":"Defining the event","paragraphs":["Define a disbursement question before collecting any data. The definition should say what counts, what does not, and which source proves the event occurred. Write two examples and one boundary case so two reviewers apply the same rule. A handling event starts when the reviewer opens the cost line and ends when the line is approved, corrected, or escalated.","Distinguish a disbursement question from a related but different case. A follow-up, a correction, and a duplicate can look similar in the queue but point to different fixes. Code the related cases separately rather than forcing them into the main category. The separation keeps the report honest about what was measured."]},{"heading":"Population and denominator","paragraphs":["The population is every invoice review session in the period. Report the number of records in the population, the number excluded, and the number in the final sample. Track the records that arrive late so the study does not silently drop them. The population is the review session, because one invoice may contain several cost questions that are handled at different times.","Use one consistent unit for the denominator. Count a reviewer handling event rather than messages, lines, or people unless the study is explicitly about that unit. If a record contains several events, split it or state that it is treated as one. Consistency matters more than precision when the source data is imperfect."]},{"heading":"Evidence sources","paragraphs":["Use the invoice cost line, the vendor receipt, and the client authorization as the primary evidence. Compare the source with the field in the billing and accounting systems and record the date each was observed. If the review time log is missing, mark the record incomplete instead of inferring the value. The invoice line, the receipt, the authorization, and the time log should share one case reference.","Keep a short evidence hierarchy so reviewers know what to trust first for disbursement review time. A signed client document is stronger than a summary written by the person who handled the case. A contemporaneous note is stronger than a later recollection, and the report should say which was used. Record the evidence type so the analysis can separate a documentation problem from a process problem."]},{"heading":"Sampling","paragraphs":["Sample across the groups that could change the result. Include different clients, matter types, staff members, and volume bands where the data allows. Draw the sample before reading the outcomes so the selection is not biased toward the obvious cases. Sample across cost types and reviewers so a single unusual vendor does not distort the average.","If the population is small, review every record and extend the period rather than lowering the evidence standard for disbursement review time. Track the records that are still open at the end of the window and report them separately. Do not drop an inconvenient case without a documented exclusion reason. A reproducible sample is more useful than a large one with unclear boundaries."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code the primary cause, the stage where it was discovered, and any secondary factor that changed the outcome. Add an unknown category for cases the evidence cannot resolve. Code the question type as missing receipt, unclear authorization, wrong matter, tax issue, duplicate, or other.","Have a second reviewer code a sample of a disbursement question and compare the results. Resolve disagreements by returning to the source rather than by majority vote. Report the agreement rate and revise any code that is used inconsistently. If the reviewers cannot agree on the definition, stop and fix the definition before continuing."]},{"heading":"Measuring time","paragraphs":["Measure the active time or the elapsed time that matches the question. Use a short log completed at the moment of the work, and separate search, decision, and communication time for a disbursement question. Report the median and the range rather than a single average. Measure active minutes in categories and report the median and range rather than a single total.","Do not convert time to a dollar figure without an approved labor rate for disbursement review time. The study measures effort and delay, not price, unless the firm has explicitly asked for a cost estimate. Keep the raw time entries with the analysis file so a reviewer can check the calculation. A precise number built on rounded guesses is less useful than a range with a clear source."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall rate, the group results, and the number behind each figure. Show the share that reached a client-facing stage, because late discovery usually costs more than early detection. Compare only groups with similar scope and duration. Report the share of review time spent on disbursement questions beside the number of invoices and cost lines reviewed.","Give the reader one table or chart that answers the main question about disbursement review time and put the detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the main pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["Source records are often incomplete, and a missing record is not proof that the event did not happen. Report the completeness of the evidence before drawing a conclusion, and name the owner of each source. Small samples, changing guidelines, and reviewer disagreement can all limit interpretation. Self-reported time can be rounded, so pair the log with a small observation sample and report the estimate.","Avoid comparing groups that differ in complexity or client requirements for disbursement review time. A long matter has more opportunity for an event, and a fixed-fee matter may have none by design. Describe the context beside the rate and avoid ranking individuals. The purpose is to improve the process, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the sample and the evidence in a controlled folder with access limited to the study team. Remove client names, amounts, and matter details from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the specific amount. Keep vendor and client details out of the analysis file and redact amounts when an example is shared.","Do not circulate a person-level or client-level list about disbursement review time outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the billing system and to quoted client messages. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common cause in the data. If the gap is a missing field, add it to the template; if it is a late approval, add a named owner and a deadline. Test the change on a defined group and compare the same measures with the baseline for disbursement review time. If search time dominates, fix the filing convention; if decision time dominates, clarify who can approve the cost.","A lower rate is not the only useful result for disbursement review time. Faster detection, clearer evidence, and fewer repeated questions can all improve the process even when the count stays similar. Report both the direct result and the service result, and keep the definitions stable. Stop the change if it shifts the work into a private channel where it cannot be reviewed."]},{"heading":"Review cadence","paragraphs":["Repeat the study on each invoice cycle and after any major change to the template, system, or client requirement. Keep the definitions and the unit stable so the comparison is meaningful. Report the records that were excluded or still open beside the main rate. Review the time study after each invoice cycle and keep the categories stable for comparison.","Review the result with billing manager and the people who maintain the record for disbursement review time. Ask which fix is easiest to sustain and which gap causes the most rework. Set one change and a follow-up date, then check whether the change held. The next study should test the repair, not just repeat the same count."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-09","thumbnail":"/thumbnails/november-09/how-much-invoice-review-time-goes-to-resolving-disbursement-questions.webp"},{"slug":"where-do-trust-transfer-requests-stall-before-approval","title":"Where do trust transfer requests stall before approval?","summary":"A stage study that follows each trust transfer request from submission to approval and reports the days lost in evidence, calculation, and sign-off.","cluster":"Trust accounting","finding":"Trust transfer delay is usually a handoff problem rather than a calculation problem, and the stage where a request waits should be recorded separately from the time spent preparing it.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks where trust transfer requests stall before approval. The unit is a trust transfer request, and the purpose is to measure the elapsed days in each approval stage without turning the result into a performance judgment. The study is limited to every trust transfer request submitted in the period and uses the definitions the firm already maintains. A trust transfer can be mathematically correct and still stall because the request lacks the evidence the approver needs.","Scope the study to the client matters with trust activity during the period. Include the cases that were approved, rejected, and still open so the denominator reflects the full workload. Exclude records that do not meet the event definition, and keep the exclusion list with the study file. State the period, the systems, and the owner so the result is not generalized beyond the sample."]},{"heading":"Defining the event","paragraphs":["Define a stalled transfer request before collecting any data. The definition should say what counts, what does not, and which source proves the event occurred. Write two examples and one boundary case so two reviewers apply the same rule. A stalled request is one that has waited longer than the firm's stated service window without a recorded decision.","Distinguish a stalled transfer request from a related but different case. A follow-up, a correction, and a duplicate can look similar in the queue but point to different fixes. Code the related cases separately rather than forcing them into the main category. The separation keeps the report honest about what was measured."]},{"heading":"Population and denominator","paragraphs":["The population is every trust transfer request submitted in the period. Report the number of records in the population, the number excluded, and the number in the final sample. Track the records that arrive late so the study does not silently drop them. The population should include requests that were withdrawn, because a withdrawal can reveal a missing step rather than a client choice.","Use one consistent unit for the denominator. Count a trust transfer request rather than messages, lines, or people unless the study is explicitly about that unit. If a record contains several events, split it or state that it is treated as one. Consistency matters more than precision when the source data is imperfect."]},{"heading":"Evidence sources","paragraphs":["Use the transfer request, the trust ledger balance, and the client authorization as the primary evidence. Compare the source with the field in the trust ledger and approval queue and record the date each was observed. If the approval record is missing, mark the record incomplete instead of inferring the value. The request, the ledger, the authorization, and the approval note should be matched before the stage times are calculated.","Keep a short evidence hierarchy so reviewers know what to trust first for trust transfer delay. A signed client document is stronger than a summary written by the person who handled the case. A contemporaneous note is stronger than a later recollection, and the report should say which was used. Record the evidence type so the analysis can separate a documentation problem from a process problem."]},{"heading":"Sampling","paragraphs":["Sample across the groups that could change the result. Include different clients, matter types, staff members, and volume bands where the data allows. Draw the sample before reading the outcomes so the selection is not biased toward the obvious cases. Sample across attorneys, clients, and request sizes so one approver's calendar does not explain the whole result.","If the population is small, review every record and extend the period rather than lowering the evidence standard for trust transfer delay. Track the records that are still open at the end of the window and report them separately. Do not drop an inconvenient case without a documented exclusion reason. A reproducible sample is more useful than a large one with unclear boundaries."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code the primary cause, the stage where it was discovered, and any secondary factor that changed the outcome. Add an unknown category for cases the evidence cannot resolve. Code the stage where the request waited, such as evidence collection, calculation, attorney review, finance review, or posting.","Have a second reviewer code a sample of a stalled transfer request and compare the results. Resolve disagreements by returning to the source rather than by majority vote. Report the agreement rate and revise any code that is used inconsistently. If the reviewers cannot agree on the definition, stop and fix the definition before continuing."]},{"heading":"Measuring time","paragraphs":["Measure the active time or the elapsed time that matches the question. Use a short log completed at the moment of the work, and separate search, decision, and communication time for a stalled transfer request. Report the median and the range rather than a single average. Measure elapsed days and active preparation time separately, and report the median for each stage.","Do not convert time to a dollar figure without an approved labor rate for trust transfer delay. The study measures effort and delay, not price, unless the firm has explicitly asked for a cost estimate. Keep the raw time entries with the analysis file so a reviewer can check the calculation. A precise number built on rounded guesses is less useful than a range with a clear source."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall rate, the group results, and the number behind each figure. Show the share that reached a client-facing stage, because late discovery usually costs more than early detection. Compare only groups with similar scope and duration. Report the share of requests that exceeded the service window beside the number of requests and the total days lost.","Give the reader one table or chart that answers the main question about trust transfer delay and put the detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the main pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["Source records are often incomplete, and a missing record is not proof that the event did not happen. Report the completeness of the evidence before drawing a conclusion, and name the owner of each source. Small samples, changing guidelines, and reviewer disagreement can all limit interpretation. A request with no recorded approval is a documentation gap even if the transfer later posted correctly.","Avoid comparing groups that differ in complexity or client requirements for trust transfer delay. A long matter has more opportunity for an event, and a fixed-fee matter may have none by design. Describe the context beside the rate and avoid ranking individuals. The purpose is to improve the process, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the sample and the evidence in a controlled folder with access limited to the study team. Remove client names, amounts, and matter details from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the specific amount. Keep client names, account numbers, and amounts out of the analysis file and restrict access to the study team.","Do not circulate a person-level or client-level list about trust transfer delay outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the billing system and to quoted client messages. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common cause in the data. If the gap is a missing field, add it to the template; if it is a late approval, add a named owner and a deadline. Test the change on a defined group and compare the same measures with the baseline for trust transfer delay. If attorney review dominates, give the approver a shorter brief; if evidence collection dominates, fix the request template.","A lower rate is not the only useful result for trust transfer delay. Faster detection, clearer evidence, and fewer repeated questions can all improve the process even when the count stays similar. Report both the direct result and the service result, and keep the definitions stable. Stop the change if it shifts the work into a private channel where it cannot be reviewed."]},{"heading":"Review cadence","paragraphs":["Repeat the study on each transfer request and after any major change to the template, system, or client requirement. Keep the definitions and the unit stable so the comparison is meaningful. Report the records that were excluded or still open beside the main rate. Review the stage times after any change to the approval path and keep the stage definitions stable.","Review the result with responsible attorney and finance owner and the people who maintain the record for trust transfer delay. Ask which fix is easiest to sustain and which gap causes the most rework. Set one change and a follow-up date, then check whether the change held. The next study should test the repair, not just repeat the same count."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-09","thumbnail":"/thumbnails/november-09/where-do-trust-transfer-requests-stall-before-approval.webp"},{"slug":"how-complete-are-client-portal-rejection-records-after-resubmission","title":"How complete are client portal rejection records after resubmission?","summary":"A completeness audit that checks whether each resubmitted rejection records the portal code, corrected line, reviewer note, approval, and final outcome.","cluster":"E-billing","finding":"A resubmission can succeed while the record remains too thin to explain what changed, and that gap makes the next rejection harder to prevent.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how complete client portal rejection records are after resubmission. The unit is a resubmitted rejection record, and the purpose is to measure the share of resubmitted records with all required fields without turning the result into a performance judgment. The study is limited to every rejection resubmitted in the period and uses the definitions the firm already maintains. A successful resubmission is not the same as a complete record, because the portal can accept a correction without preserving the reason.","Scope the study to the portals and matters with at least one resubmission during the period. Include the cases that were approved, rejected, and still open so the denominator reflects the full workload. Exclude records that do not meet the event definition, and keep the exclusion list with the study file. State the period, the systems, and the owner so the result is not generalized beyond the sample."]},{"heading":"Defining the event","paragraphs":["Define an incomplete rejection record before collecting any data. The definition should say what counts, what does not, and which source proves the event occurred. Write two examples and one boundary case so two reviewers apply the same rule. A complete record links the portal code, the original line, the corrected line, the reviewer, and the approval that allowed the change.","Distinguish an incomplete rejection record from a related but different case. A follow-up, a correction, and a duplicate can look similar in the queue but point to different fixes. Code the related cases separately rather than forcing them into the main category. The separation keeps the report honest about what was measured."]},{"heading":"Population and denominator","paragraphs":["The population is every rejection resubmitted in the period. Report the number of records in the population, the number excluded, and the number in the final sample. Track the records that arrive late so the study does not silently drop them. The population is every resubmitted rejection, including those that were accepted on the first attempt after correction.","Use one consistent unit for the denominator. Count a resubmitted rejection record rather than messages, lines, or people unless the study is explicitly about that unit. If a record contains several events, split it or state that it is treated as one. Consistency matters more than precision when the source data is imperfect."]},{"heading":"Evidence sources","paragraphs":["Use the rejection code, the corrected invoice line, and the reviewer note as the primary evidence. Compare the source with the field in the portal and billing record and record the date each was observed. If the resubmission outcome is missing, mark the record incomplete instead of inferring the value. The resubmission outcome and the reviewer note should be read together to see whether the record explains the change.","Keep a short evidence hierarchy so reviewers know what to trust first for rejection record completeness. A signed client document is stronger than a summary written by the person who handled the case. A contemporaneous note is stronger than a later recollection, and the report should say which was used. Record the evidence type so the analysis can separate a documentation problem from a process problem."]},{"heading":"Sampling","paragraphs":["Sample across the groups that could change the result. Include different clients, matter types, staff members, and volume bands where the data allows. Draw the sample before reading the outcomes so the selection is not biased toward the obvious cases. Sample across portals and rejection types so one portal's field rules do not define the standard for every client.","If the population is small, review every record and extend the period rather than lowering the evidence standard for rejection record completeness. Track the records that are still open at the end of the window and report them separately. Do not drop an inconvenient case without a documented exclusion reason. A reproducible sample is more useful than a large one with unclear boundaries."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code the primary cause, the stage where it was discovered, and any secondary factor that changed the outcome. Add an unknown category for cases the evidence cannot resolve. Code each required field as present, partial, or missing, and keep the field list short enough to score consistently.","Have a second reviewer code a sample of an incomplete rejection record and compare the results. Resolve disagreements by returning to the source rather than by majority vote. Report the agreement rate and revise any code that is used inconsistently. If the reviewers cannot agree on the definition, stop and fix the definition before continuing."]},{"heading":"Measuring time","paragraphs":["Measure the active time or the elapsed time that matches the question. Use a short log completed at the moment of the work, and separate search, decision, and communication time for an incomplete rejection record. Report the median and the range rather than a single average. Measure the time from rejection to resubmission and the number of attempts, because a fast resubmission can still hide a thin record.","Do not convert time to a dollar figure without an approved labor rate for rejection record completeness. The study measures effort and delay, not price, unless the firm has explicitly asked for a cost estimate. Keep the raw time entries with the analysis file so a reviewer can check the calculation. A precise number built on rounded guesses is less useful than a range with a clear source."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall rate, the group results, and the number behind each figure. Show the share that reached a client-facing stage, because late discovery usually costs more than early detection. Compare only groups with similar scope and duration. Report the completeness rate beside the number of records and the share that were accepted after the first resubmission.","Give the reader one table or chart that answers the main question about rejection record completeness and put the detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the main pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["Source records are often incomplete, and a missing record is not proof that the event did not happen. Report the completeness of the evidence before drawing a conclusion, and name the owner of each source. Small samples, changing guidelines, and reviewer disagreement can all limit interpretation. A record that cannot be understood without asking the reviewer is incomplete even if every portal field was filled.","Avoid comparing groups that differ in complexity or client requirements for rejection record completeness. A long matter has more opportunity for an event, and a fixed-fee matter may have none by design. Describe the context beside the rate and avoid ranking individuals. The purpose is to improve the process, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the sample and the evidence in a controlled folder with access limited to the study team. Remove client names, amounts, and matter details from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the specific amount. Remove client and invoice details from the scoring sheet and keep screenshots in the controlled folder.","Do not circulate a person-level or client-level list about rejection record completeness outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the billing system and to quoted client messages. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common cause in the data. If the gap is a missing field, add it to the template; if it is a late approval, add a named owner and a deadline. Test the change on a defined group and compare the same measures with the baseline for rejection record completeness. If the reviewer note is the weakest field, add a short required prompt rather than a longer free-text box.","A lower rate is not the only useful result for rejection record completeness. Faster detection, clearer evidence, and fewer repeated questions can all improve the process even when the count stays similar. Report both the direct result and the service result, and keep the definitions stable. Stop the change if it shifts the work into a private channel where it cannot be reviewed."]},{"heading":"Review cadence","paragraphs":["Repeat the study on each submission window and after any major change to the template, system, or client requirement. Keep the definitions and the unit stable so the comparison is meaningful. Report the records that were excluded or still open beside the main rate. Review the audit after each portal or template change and keep the scoring guide stable.","Review the result with e-billing manager and the people who maintain the record for rejection record completeness. Ask which fix is easiest to sustain and which gap causes the most rework. Set one change and a follow-up date, then check whether the change held. The next study should test the repair, not just repeat the same count."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-09","thumbnail":"/thumbnails/november-09/how-complete-are-client-portal-rejection-records-after-resubmission.webp"},{"slug":"how-often-do-coverage-gaps-appear-during-billing-staff-absences","title":"How often do coverage gaps appear during billing staff absences?","summary":"An absence study that records which billing queues lost a named owner, how long the gap lasted, and which handoff evidence was missing when coverage began.","cluster":"Role design","finding":"Coverage gaps are better measured by queue readiness than by attendance, because a backup can be present and still lack the access or context needed to act.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how often billing queues lack a ready backup during staff absences. The unit is an absence day or queue handoff, and the purpose is to measure the share of queues without a ready backup without turning the result into a performance judgment. The study is limited to every scheduled and unscheduled billing absence in the period and uses the definitions the firm already maintains. Attendance is easy to count, but the real question is whether the person covering the queue could act on the day.","Scope the study to the billing team and the queues it owns during the period. Include the cases that were approved, rejected, and still open so the denominator reflects the full workload. Exclude records that do not meet the event definition, and keep the exclusion list with the study file. State the period, the systems, and the owner so the result is not generalized beyond the sample."]},{"heading":"Defining the event","paragraphs":["Define a coverage gap before collecting any data. The definition should say what counts, what does not, and which source proves the event occurred. Write two examples and one boundary case so two reviewers apply the same rule. A coverage gap exists when a queue has no named backup, no working access, or no handoff note for an open item.","Distinguish a coverage gap from a related but different case. A follow-up, a correction, and a duplicate can look similar in the queue but point to different fixes. Code the related cases separately rather than forcing them into the main category. The separation keeps the report honest about what was measured."]},{"heading":"Population and denominator","paragraphs":["The population is every scheduled and unscheduled billing absence in the period. Report the number of records in the population, the number excluded, and the number in the final sample. Track the records that arrive late so the study does not silently drop them. The population should include planned leave as well as sudden absences, because planned leave can still expose a weak backup.","Use one consistent unit for the denominator. Count an absence day or queue handoff rather than messages, lines, or people unless the study is explicitly about that unit. If a record contains several events, split it or state that it is treated as one. Consistency matters more than precision when the source data is imperfect."]},{"heading":"Evidence sources","paragraphs":["Use the absence record, the coverage roster, and the access checklist as the primary evidence. Compare the source with the field in the queue and access records and record the date each was observed. If the handoff note is missing, mark the record incomplete instead of inferring the value. The roster, the access checklist, and the handoff note should be checked against the queue that actually needed coverage.","Keep a short evidence hierarchy so reviewers know what to trust first for billing coverage gaps. A signed client document is stronger than a summary written by the person who handled the case. A contemporaneous note is stronger than a later recollection, and the report should say which was used. Record the evidence type so the analysis can separate a documentation problem from a process problem."]},{"heading":"Sampling","paragraphs":["Sample across the groups that could change the result. Include different clients, matter types, staff members, and volume bands where the data allows. Draw the sample before reading the outcomes so the selection is not biased toward the obvious cases. Sample across queues and shift patterns so one specialist's absence does not define the result for the whole team.","If the population is small, review every record and extend the period rather than lowering the evidence standard for billing coverage gaps. Track the records that are still open at the end of the window and report them separately. Do not drop an inconvenient case without a documented exclusion reason. A reproducible sample is more useful than a large one with unclear boundaries."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code the primary cause, the stage where it was discovered, and any secondary factor that changed the outcome. Add an unknown category for cases the evidence cannot resolve. Code the gap as missing owner, missing access, missing context, missing deadline, or no gap, and allow a secondary code.","Have a second reviewer code a sample of a coverage gap and compare the results. Resolve disagreements by returning to the source rather than by majority vote. Report the agreement rate and revise any code that is used inconsistently. If the reviewers cannot agree on the definition, stop and fix the definition before continuing."]},{"heading":"Measuring time","paragraphs":["Measure the active time or the elapsed time that matches the question. Use a short log completed at the moment of the work, and separate search, decision, and communication time for a coverage gap. Report the median and the range rather than a single average. Measure the days the queue waited and the active time the backup needed to become productive.","Do not convert time to a dollar figure without an approved labor rate for billing coverage gaps. The study measures effort and delay, not price, unless the firm has explicitly asked for a cost estimate. Keep the raw time entries with the analysis file so a reviewer can check the calculation. A precise number built on rounded guesses is less useful than a range with a clear source."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall rate, the group results, and the number behind each figure. Show the share that reached a client-facing stage, because late discovery usually costs more than early detection. Compare only groups with similar scope and duration. Report the gap share beside the number of absence days and the number of queues affected.","Give the reader one table or chart that answers the main question about billing coverage gaps and put the detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the main pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["Source records are often incomplete, and a missing record is not proof that the event did not happen. Report the completeness of the evidence before drawing a conclusion, and name the owner of each source. Small samples, changing guidelines, and reviewer disagreement can all limit interpretation. A backup who eventually recovers access still represents a gap if client work waited during the outage.","Avoid comparing groups that differ in complexity or client requirements for billing coverage gaps. A long matter has more opportunity for an event, and a fixed-fee matter may have none by design. Describe the context beside the rate and avoid ranking individuals. The purpose is to improve the process, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the sample and the evidence in a controlled folder with access limited to the study team. Remove client names, amounts, and matter details from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the specific amount. Keep individual attendance and health details out of the analysis file and report roles rather than people.","Do not circulate a person-level or client-level list about billing coverage gaps outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the billing system and to quoted client messages. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common cause in the data. If the gap is a missing field, add it to the template; if it is a late approval, add a named owner and a deadline. Test the change on a defined group and compare the same measures with the baseline for billing coverage gaps. If missing access dominates, fix the recovery process; if missing context dominates, fix the handoff template.","A lower rate is not the only useful result for billing coverage gaps. Faster detection, clearer evidence, and fewer repeated questions can all improve the process even when the count stays similar. Report both the direct result and the service result, and keep the definitions stable. Stop the change if it shifts the work into a private channel where it cannot be reviewed."]},{"heading":"Review cadence","paragraphs":["Repeat the study on each absence and quarterly drill and after any major change to the template, system, or client requirement. Keep the definitions and the unit stable so the comparison is meaningful. Report the records that were excluded or still open beside the main rate. Review the result after each leave cycle and after any role change, and keep the gap definition stable.","Review the result with billing manager and the people who maintain the record for billing coverage gaps. Ask which fix is easiest to sustain and which gap causes the most rework. Set one change and a follow-up date, then check whether the change held. The next study should test the repair, not just repeat the same count."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-09","thumbnail":"/thumbnails/november-09/how-often-do-coverage-gaps-appear-during-billing-staff-absences.webp"},{"slug":"what-share-of-budget-alerts-reach-the-partner-before-the-prebill","title":"What share of budget alerts reach the partner before the prebill?","summary":"A delivery study that compares each phase budget alert with the prebill date and reports how many alerts arrived in time to change the work.","cluster":"Budgets","finding":"An alert that arrives after the prebill is a report rather than a control, so the useful measure is the share delivered while the partner can still act.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks what share of phase budget alerts reach the partner before the prebill. The unit is a budget alert, and the purpose is to measure the share of alerts delivered before the prebill without turning the result into a performance judgment. The study is limited to every phase budget alert generated in the period and uses the definitions the firm already maintains. A budget alert is useful only if it arrives while the partner can still change the staffing or the scope.","Scope the study to the active matters with an approved phase budget during the period. Include the cases that were approved, rejected, and still open so the denominator reflects the full workload. Exclude records that do not meet the event definition, and keep the exclusion list with the study file. State the period, the systems, and the owner so the result is not generalized beyond the sample."]},{"heading":"Defining the event","paragraphs":["Define a late budget alert before collecting any data. The definition should say what counts, what does not, and which source proves the event occurred. Write two examples and one boundary case so two reviewers apply the same rule. An alert is late when its delivery date is on or after the prebill date, even if the partner reads it later.","Distinguish a late budget alert from a related but different case. A follow-up, a correction, and a duplicate can look similar in the queue but point to different fixes. Code the related cases separately rather than forcing them into the main category. The separation keeps the report honest about what was measured."]},{"heading":"Population and denominator","paragraphs":["The population is every phase budget alert generated in the period. Report the number of records in the population, the number excluded, and the number in the final sample. Track the records that arrive late so the study does not silently drop them. The population should include alerts that were suppressed or dismissed, because a silent alert is still part of the control result.","Use one consistent unit for the denominator. Count a budget alert rather than messages, lines, or people unless the study is explicitly about that unit. If a record contains several events, split it or state that it is treated as one. Consistency matters more than precision when the source data is imperfect."]},{"heading":"Evidence sources","paragraphs":["Use the approved phase budget, the alert record, and the prebill date as the primary evidence. Compare the source with the field in the time and billing alert queue and record the date each was observed. If the partner response is missing, mark the record incomplete instead of inferring the value. The budget record, the alert timestamp, the prebill date, and the partner response should be matched for each case.","Keep a short evidence hierarchy so reviewers know what to trust first for budget alert timing. A signed client document is stronger than a summary written by the person who handled the case. A contemporaneous note is stronger than a later recollection, and the report should say which was used. Record the evidence type so the analysis can separate a documentation problem from a process problem."]},{"heading":"Sampling","paragraphs":["Sample across the groups that could change the result. Include different clients, matter types, staff members, and volume bands where the data allows. Draw the sample before reading the outcomes so the selection is not biased toward the obvious cases. Sample across matter types and alert thresholds so one large matter does not dominate the result.","If the population is small, review every record and extend the period rather than lowering the evidence standard for budget alert timing. Track the records that are still open at the end of the window and report them separately. Do not drop an inconvenient case without a documented exclusion reason. A reproducible sample is more useful than a large one with unclear boundaries."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code the primary cause, the stage where it was discovered, and any secondary factor that changed the outcome. Add an unknown category for cases the evidence cannot resolve. Code the outcome as delivered before prebill, delivered after prebill, not delivered, or dismissed without a decision.","Have a second reviewer code a sample of a late budget alert and compare the results. Resolve disagreements by returning to the source rather than by majority vote. Report the agreement rate and revise any code that is used inconsistently. If the reviewers cannot agree on the definition, stop and fix the definition before continuing."]},{"heading":"Measuring time","paragraphs":["Measure the active time or the elapsed time that matches the question. Use a short log completed at the moment of the work, and separate search, decision, and communication time for a late budget alert. Report the median and the range rather than a single average. Measure the days between alert and prebill and the time from alert to partner response.","Do not convert time to a dollar figure without an approved labor rate for budget alert timing. The study measures effort and delay, not price, unless the firm has explicitly asked for a cost estimate. Keep the raw time entries with the analysis file so a reviewer can check the calculation. A precise number built on rounded guesses is less useful than a range with a clear source."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall rate, the group results, and the number behind each figure. Show the share that reached a client-facing stage, because late discovery usually costs more than early detection. Compare only groups with similar scope and duration. Report the on-time share beside the number of alerts, matters, and alerts that led to a recorded change.","Give the reader one table or chart that answers the main question about budget alert timing and put the detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the main pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["Source records are often incomplete, and a missing record is not proof that the event did not happen. Report the completeness of the evidence before drawing a conclusion, and name the owner of each source. Small samples, changing guidelines, and reviewer disagreement can all limit interpretation. An alert that was sent but never read is a delivery problem, not evidence that the partner ignored the budget.","Avoid comparing groups that differ in complexity or client requirements for budget alert timing. A long matter has more opportunity for an event, and a fixed-fee matter may have none by design. Describe the context beside the rate and avoid ranking individuals. The purpose is to improve the process, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the sample and the evidence in a controlled folder with access limited to the study team. Remove client names, amounts, and matter details from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the specific amount. Keep client names and fee amounts out of the analysis file and report ranges when a small group could be identified.","Do not circulate a person-level or client-level list about budget alert timing outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the billing system and to quoted client messages. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common cause in the data. If the gap is a missing field, add it to the template; if it is a late approval, add a named owner and a deadline. Test the change on a defined group and compare the same measures with the baseline for budget alert timing. If late delivery dominates, move the alert threshold earlier; if non-delivery dominates, fix the queue or owner.","A lower rate is not the only useful result for budget alert timing. Faster detection, clearer evidence, and fewer repeated questions can all improve the process even when the count stays similar. Report both the direct result and the service result, and keep the definitions stable. Stop the change if it shifts the work into a private channel where it cannot be reviewed."]},{"heading":"Review cadence","paragraphs":["Repeat the study on weekly during active phases and after any major change to the template, system, or client requirement. Keep the definitions and the unit stable so the comparison is meaningful. Report the records that were excluded or still open beside the main rate. Review the result after each phase cycle and keep the alert definition stable so periods can be compared.","Review the result with budget owner or partner and the people who maintain the record for budget alert timing. Ask which fix is easiest to sustain and which gap causes the most rework. Set one change and a follow-up date, then check whether the change held. The next study should test the repair, not just repeat the same count."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-09","thumbnail":"/thumbnails/november-09/what-share-of-budget-alerts-reach-the-partner-before-the-prebill.webp"}];
